using System;
using UnityEngine;
using InControl;
using Framework.Input;
using Framework.Input.Integrations.InControl;
using Framework.Save;
using Framework.Save.Integrations.EasySave;

namespace Game.Input
{
    /// <summary>
    /// ゲーム内の入力受付モード。
    /// </summary>
    public enum GameInputMode
    {
        /// <summary>すべての入力を無効にする。</summary>
        Disabled = 0,

        /// <summary>ゲーム操作のみ有効にする。</summary>
        Gameplay = 1,

        /// <summary>UI操作のみ有効にする。</summary>
        UI = 2,

        /// <summary>両方の操作を有効にする。</summary>
        Both = 3
    }

    /// <summary>
    /// ゲーム全体の入力を統合管理するクラス。
    ///
    /// 操作セットの生成・破棄、入力モードの切り替え、
    /// 入力取得、キー割り当ての保存・復元を担当する。
    ///
    /// 保存処理にはISaveProviderを使用する。
    /// キャラクターやUIそのものの制御は行わない。
    /// </summary>
    [DisallowMultipleComponent]
    public class GameInputManager :
        MonoBehaviour,
        IInputProvider<GameInputAction>
    {
        #region Constants

        /// <summary>
        /// キー割り当てデータを保存する識別キー。
        /// </summary>
        private const string BindingSaveKey =
            "InputBindings";

        #endregion

        #region Inspector Fields

        [Header("初期化設定")]

        /// <summary>Awake時に自動初期化するか。</summary>
        [SerializeField]
        [Tooltip("Awake時に入力システムを初期化する")]
        private bool initializeOnAwake = true;

        /// <summary>初期化直後の入力モード。</summary>
        [SerializeField]
        [Tooltip("初期化直後の入力受付モード")]
        private GameInputMode initialMode =
            GameInputMode.Gameplay;

        [Header("入力制御設定")]

        /// <summary>
        /// モード変更フレームの入力を遮断するか。
        /// </summary>
        [SerializeField]
        [Tooltip("入力モード変更フレームの入力を遮断する")]
        private bool blockInputOnModeChange = true;

        [Header("キー設定保存")]

        /// <summary>
        /// 初期化時に保存済みの設定を復元するか。
        /// </summary>
        [SerializeField]
        [Tooltip("初期化時に保存済みのキー設定を読み込む")]
        private bool loadBindingsOnInitialize = true;

        /// <summary>
        /// キー割り当てを保存するファイルパス。
        /// </summary>
        [SerializeField]
        [Tooltip("Easy Save 3で使用する保存ファイルパス")]
        private string saveFilePath =
            "SaveData/InputSettings.es3";

        #endregion

        #region Runtime Fields

        /// <summary>ゲーム操作セット。</summary>
        private GameplayActions gameplayActions;

        /// <summary>UI操作セット。</summary>
        private UIActions uiActions;

        /// <summary>ゲーム操作用Adapter。</summary>
        private InControlInputAdapter<GameInputAction>
            gameplayAdapter;

        /// <summary>UI操作用Adapter。</summary>
        private InControlInputAdapter<GameInputAction>
            uiAdapter;

        /// <summary>キー設定の保存Provider。</summary>
        private ISaveProvider saveProvider;

        /// <summary>現在の入力モード。</summary>
        private GameInputMode currentMode =
            GameInputMode.Disabled;

        /// <summary>初期化が完了しているか。</summary>
        private bool isInitialized;

        /// <summary>入力全体が有効になっているか。</summary>
        private bool isInputEnabled;

        /// <summary>入力を遮断するフレーム番号。</summary>
        private int blockedFrame = -1;

        #endregion

        #region Properties

        /// <summary>入力システムの初期化状態。</summary>
        public bool IsInitialized => isInitialized;

        /// <summary>現在入力を取得できる状態か。</summary>
        public bool IsInputEnabled =>
            isInitialized &&
            isInputEnabled &&
            isActiveAndEnabled &&
            currentMode != GameInputMode.Disabled &&
            !IsInputBlocked;

        /// <summary>現在の入力モード。</summary>
        public GameInputMode CurrentMode => currentMode;

        /// <summary>入力遮断フレーム中か。</summary>
        public bool IsInputBlocked =>
            Time.frameCount <= blockedFrame;

        /// <summary>ゲーム操作が有効か。</summary>
        public bool IsGameplayInputEnabled =>
            IsInputEnabled &&
            gameplayAdapter != null &&
            gameplayAdapter.IsInputEnabled;

        /// <summary>UI操作が有効か。</summary>
        public bool IsUIInputEnabled =>
            IsInputEnabled &&
            uiAdapter != null &&
            uiAdapter.IsInputEnabled;

        /// <summary>登録されているゲーム操作数。</summary>
        public int GameplayActionCount =>
            gameplayAdapter?.ActionCount ?? 0;

        /// <summary>登録されているUI操作数。</summary>
        public int UIActionCount =>
            uiAdapter?.ActionCount ?? 0;

        /// <summary>登録されている全操作数。</summary>
        public int ActionCount =>
            GameplayActionCount + UIActionCount;

        /// <summary>保存Providerが設定されているか。</summary>
        public bool HasSaveProvider =>
            saveProvider != null;

        #endregion

        #region Events

        /// <summary>
        /// 入力モード変更時のイベント。
        /// 引数は変更前と変更後の入力モード。
        /// </summary>
        public event Action<GameInputMode, GameInputMode>
            InputModeChanged;

        /// <summary>
        /// キー割り当ての復元・初期化時のイベント。
        /// </summary>
        public event Action BindingsChanged;

        /// <summary>
        /// キー設定保存成功時のイベント。
        /// </summary>
        public event Action BindingsSaved;

        #endregion

        #region Unity Methods

        /// <summary>コンポーネント初期化時の処理。</summary>
        private void Awake()
        {
            if (initializeOnAwake)
            {
                Initialize();
            }
        }

        /// <summary>コンポーネント有効化時の処理。</summary>
        private void OnEnable()
        {
            if (!isInitialized)
            {
                return;
            }

            ApplyInputMode();
            BlockCurrentFrame();
        }

        /// <summary>コンポーネント無効化時の処理。</summary>
        private void OnDisable()
        {
            if (isInitialized)
            {
                ApplyInputMode();
            }
        }

        /// <summary>コンポーネント破棄時の処理。</summary>
        private void OnDestroy()
        {
            Shutdown();
        }

        #endregion

        #region Initialization Methods

        /// <summary>
        /// Inspectorの設定に従って初期化する。
        /// </summary>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool Initialize()
        {
            return Initialize(loadBindingsOnInitialize);
        }

        /// <summary>
        /// 保存設定の復元有無を指定して初期化する。
        /// </summary>
        /// <param name="loadSavedBindings">
        /// 保存済み設定を復元するか
        /// </param>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool Initialize(bool loadSavedBindings)
        {
            if (isInitialized)
            {
                return true;
            }

            try
            {
                // 通常使用する保存Providerを生成する。
                ISaveProvider provider =
                    new EasySaveProvider(saveFilePath);

                return Initialize(
                    provider,
                    loadSavedBindings);
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// 外部から指定された保存Providerを使用して
        /// 入力システムを初期化する。
        ///
        /// テストや保存方式の変更時に利用できる。
        /// </summary>
        /// <param name="provider">使用する保存Provider</param>
        /// <param name="loadSavedBindings">
        /// 保存済み設定を復元するか
        /// </param>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool Initialize(
            ISaveProvider provider,
            bool loadSavedBindings = true)
        {
            if (provider == null)
            {
                throw new ArgumentNullException(
                    nameof(provider));
            }

            if (isInitialized)
            {
                // 初期化済みの場合は保存先を変更しない。
                return ReferenceEquals(
                    saveProvider,
                    provider);
            }

            try
            {
                saveProvider = provider;

                gameplayActions =
                    GameplayActions.CreateWithDefaultBindings();

                uiActions =
                    UIActions.CreateWithDefaultBindings();

                gameplayAdapter =
                    new InControlInputAdapter<GameInputAction>();

                uiAdapter =
                    new InControlInputAdapter<GameInputAction>();

                RegisterAllActions();

                gameplayAdapter.Initialize(false);
                uiAdapter.Initialize(false);

                isInitialized = true;
                isInputEnabled = true;

                // 復元に失敗しても初期設定で起動する。
                if (loadSavedBindings && !LoadBindings())
                {
                    Debug.LogWarning(
                        "キー設定を復元できませんでした。" +
                        "初期設定で起動します。",
                        this);

                    if (!ResetBindings())
                    {
                        throw new InvalidOperationException(
                            "キー設定の初期化に失敗しました。");
                    }
                }

                SetInputMode(initialMode);

                return true;
            }
            catch (Exception exception)
            {
                Shutdown();

                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// 定義済みの操作を各Adapterへ登録する。
        /// </summary>
        private void RegisterAllActions()
        {
            foreach (GameInputAction action in
                Enum.GetValues(typeof(GameInputAction)))
            {
                // ゲーム操作を登録する。
                if (gameplayActions.TryGetPlayerAction(
                    action,
                    out PlayerAction gameplayAction))
                {
                    gameplayAdapter.RegisterAction(
                        action,
                        gameplayAction);
                }

                if (gameplayActions.TryGetTwoAxisAction(
                    action,
                    out PlayerTwoAxisAction gameplayAxis))
                {
                    gameplayAdapter.RegisterTwoAxisAction(
                        action,
                        gameplayAxis);
                }

                // UI操作を登録する。
                if (uiActions.TryGetPlayerAction(
                    action,
                    out PlayerAction uiAction))
                {
                    uiAdapter.RegisterAction(
                        action,
                        uiAction);
                }

                if (uiActions.TryGetTwoAxisAction(
                    action,
                    out PlayerTwoAxisAction uiAxis))
                {
                    uiAdapter.RegisterTwoAxisAction(
                        action,
                        uiAxis);
                }
            }
        }

        /// <summary>
        /// 入力システムを終了する。
        ///
        /// 保存ファイルの削除や自動保存は行わない。
        /// 終了後は再初期化できる。
        /// </summary>
        public void Shutdown()
        {
            gameplayAdapter?.Dispose();
            uiAdapter?.Dispose();

            gameplayAdapter = null;
            uiAdapter = null;

            gameplayActions?.Destroy();
            uiActions?.Destroy();

            gameplayActions = null;
            uiActions = null;

            saveProvider = null;

            isInitialized = false;
            isInputEnabled = false;

            currentMode = GameInputMode.Disabled;
            blockedFrame = -1;
        }

        #endregion

        #region Input Mode Methods

        /// <summary>入力受付モードを変更する。</summary>
        /// <param name="mode">変更後の入力モード</param>
        /// <returns>変更可能な場合はtrue</returns>
        public bool SetInputMode(GameInputMode mode)
        {
            if (!Enum.IsDefined(typeof(GameInputMode), mode))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(mode));
            }

            if (!isInitialized)
            {
                return false;
            }

            if (currentMode == mode)
            {
                return true;
            }

            GameInputMode previousMode = currentMode;

            currentMode = mode;

            ApplyInputMode();

            // モード切り替え直後の誤入力を防止する。
            if (blockInputOnModeChange)
            {
                BlockCurrentFrame();
            }

            InputModeChanged?.Invoke(
                previousMode,
                currentMode);

            return true;
        }

        /// <summary>
        /// 現在の入力モードを各Adapterへ反映する。
        /// </summary>
        private void ApplyInputMode()
        {
            if (!isInitialized)
            {
                return;
            }

            bool canEnable =
                isInputEnabled && isActiveAndEnabled;

            bool enableGameplay =
                canEnable &&
                (currentMode == GameInputMode.Gameplay ||
                 currentMode == GameInputMode.Both);

            bool enableUI =
                canEnable &&
                (currentMode == GameInputMode.UI ||
                 currentMode == GameInputMode.Both);

            gameplayAdapter.SetInputEnabled(
                enableGameplay);

            uiAdapter.SetInputEnabled(enableUI);
        }

        /// <summary>
        /// 入力全体の有効状態を設定する。
        /// 現在の入力モードは維持する。
        /// </summary>
        /// <param name="enabled">有効にする場合はtrue</param>
        public void SetInputEnabled(bool enabled)
        {
            if (!isInitialized ||
                isInputEnabled == enabled)
            {
                return;
            }

            isInputEnabled = enabled;

            ApplyInputMode();

            if (enabled)
            {
                BlockCurrentFrame();
            }
        }

        /// <summary>
        /// 現在のフレーム中の入力取得を遮断する。
        /// </summary>
        public void BlockCurrentFrame()
        {
            blockedFrame = Time.frameCount;
        }

        #endregion

        #region Action Lookup Methods

        /// <summary>
        /// 操作IDに対応するAdapterを取得する。
        /// </summary>
        /// <param name="action">検索する操作ID</param>
        /// <returns>対応するAdapter。未登録時はnull</returns>
        private InControlInputAdapter<GameInputAction>
            GetAdapter(GameInputAction action)
        {
            if (!isInitialized)
            {
                return null;
            }

            if (gameplayAdapter.HasAction(action))
            {
                return gameplayAdapter;
            }

            if (uiAdapter.HasAction(action))
            {
                return uiAdapter;
            }

            return null;
        }

        /// <summary>指定操作が登録されているか確認する。</summary>
        /// <param name="action">確認する操作ID</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool HasAction(GameInputAction action)
        {
            return GetAdapter(action) != null;
        }

        /// <summary>
        /// キー設定変更用の個別操作を取得する。
        /// </summary>
        /// <param name="action">取得する操作ID</param>
        /// <param name="playerAction">取得された個別操作</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetPlayerAction(
            GameInputAction action,
            out PlayerAction playerAction)
        {
            playerAction = null;

            var adapter = GetAdapter(action);

            return adapter != null &&
                   adapter.TryGetPlayerAction(
                       action,
                       out playerAction);
        }

        #endregion

        #region Input Access Methods

        /// <summary>ボタンの押下状態を取得する。</summary>
        /// <param name="action">取得する操作ID</param>
        /// <returns>押されている場合はtrue</returns>
        public bool GetButton(GameInputAction action)
        {
            return IsInputEnabled &&
                   (GetAdapter(action)?.GetButton(action)
                    ?? false);
        }

        /// <summary>ボタンを押した瞬間を取得する。</summary>
        /// <param name="action">取得する操作ID</param>
        /// <returns>押されたフレームの場合はtrue</returns>
        public bool GetButtonDown(GameInputAction action)
        {
            return IsInputEnabled &&
                   (GetAdapter(action)?.GetButtonDown(action)
                    ?? false);
        }

        /// <summary>ボタンを離した瞬間を取得する。</summary>
        /// <param name="action">取得する操作ID</param>
        /// <returns>離されたフレームの場合はtrue</returns>
        public bool GetButtonUp(GameInputAction action)
        {
            return IsInputEnabled &&
                   (GetAdapter(action)?.GetButtonUp(action)
                    ?? false);
        }

        /// <summary>1軸入力値を取得する。</summary>
        /// <param name="action">取得する操作ID</param>
        /// <returns>入力値。無効時は0</returns>
        public float GetAxis(GameInputAction action)
        {
            if (!IsInputEnabled)
            {
                return 0f;
            }

            return GetAdapter(action)?.GetAxis(action)
                   ?? 0f;
        }

        /// <summary>2軸入力値を取得する。</summary>
        /// <param name="action">取得する操作ID</param>
        /// <returns>入力ベクトル。無効時はzero</returns>
        public Vector2 GetVector2(GameInputAction action)
        {
            if (!IsInputEnabled)
            {
                return Vector2.zero;
            }

            return GetAdapter(action)?.GetVector2(action)
                   ?? Vector2.zero;
        }

        #endregion

        #region Binding Data Methods

        /// <summary>
        /// 現在のキー割り当てを保存データへ変換する。
        /// </summary>
        /// <returns>現在のキー割り当てデータ</returns>
        public InputBindingSaveData CaptureBindings()
        {
            if (!isInitialized)
            {
                throw new InvalidOperationException(
                    "入力システムが初期化されていません。");
            }

            return new InputBindingSaveData
            {
                Version =
                    InputBindingSaveData.CurrentVersion,

                GameplayBindings =
                    gameplayActions.Save(),

                UIBindings =
                    uiActions.Save()
            };
        }

        /// <summary>
        /// 指定されたキー割り当てデータを適用する。
        ///
        /// 保存ファイルへの書き込みは行わない。
        /// 適用に失敗した場合は復元前の状態へ戻す。
        /// </summary>
        /// <param name="data">適用するキー設定</param>
        /// <returns>適用に成功した場合はtrue</returns>
        public bool ApplyBindings(InputBindingSaveData data)
        {
            if (!isInitialized ||
                data == null ||
                !data.IsValid())
            {
                return false;
            }

            InputBindingSaveData backup = null;

            try
            {
                // 適用失敗時に備えて現在の設定を退避する。
                backup = CaptureBindings();

                gameplayActions.Load(
                    data.GameplayBindings);

                uiActions.Load(
                    data.UIBindings);
            }
            catch (Exception exception)
            {
                Debug.LogWarning(
                    "キー割り当ての適用に失敗しました。\n" +
                    exception.Message,
                    this);

                // 適用前の設定へ戻す。
                if (backup != null)
                {
                    try
                    {
                        gameplayActions.Load(
                            backup.GameplayBindings);

                        uiActions.Load(
                            backup.UIBindings);
                    }
                    catch (Exception restoreException)
                    {
                        Debug.LogException(
                            restoreException,
                            this);

                        // 復元できない場合は初期設定へ戻す。
                        ResetBindings();
                    }
                }

                BlockCurrentFrame();

                return false;
            }

            BlockCurrentFrame();

            BindingsChanged?.Invoke();

            return true;
        }

        #endregion

        #region Binding Save Methods

        /// <summary>
        /// 現在のキー割り当てを保存する。
        /// </summary>
        /// <returns>保存に成功した場合はtrue</returns>
        public bool SaveBindings()
        {
            if (!isInitialized || saveProvider == null)
            {
                return false;
            }

            try
            {
                InputBindingSaveData data =
                    CaptureBindings();

                if (!data.IsValid())
                {
                    return false;
                }

                // 両操作セットを一つのデータとして保存する。
                saveProvider.Save(
                    BindingSaveKey,
                    data);

                saveProvider.Flush();
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }

            BindingsSaved?.Invoke();

            return true;
        }

        /// <summary>
        /// 保存済みのキー割り当てを復元する。
        ///
        /// 保存データが存在しない場合は
        /// 現在の設定を維持する。
        /// </summary>
        /// <returns>復元処理に成功した場合はtrue</returns>
        public bool LoadBindings()
        {
            if (!isInitialized || saveProvider == null)
            {
                return false;
            }

            InputBindingSaveData data;

            try
            {
                if (!saveProvider.Exists(BindingSaveKey))
                {
                    return true;
                }

                // 未保存と読み込み失敗を区別するため、
                // 存在確認後にLoadを使用する。
                data = saveProvider.Load<InputBindingSaveData>(
                    BindingSaveKey,
                    null);
            }
            catch (Exception exception)
            {
                Debug.LogWarning(
                    "キー設定の読み込みに失敗しました。\n" +
                    exception.Message,
                    this);

                return false;
            }

            if (data == null || !data.IsValid())
            {
                Debug.LogWarning(
                    "キー設定の保存形式が無効、" +
                    "または未対応です。",
                    this);

                return false;
            }

            return ApplyBindings(data);
        }

        /// <summary>
        /// キー割り当てを初期設定へ戻す。
        /// 保存済みデータは変更しない。
        /// </summary>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool ResetBindings()
        {
            if (!isInitialized)
            {
                return false;
            }

            try
            {
                gameplayActions.Reset();
                uiActions.Reset();
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }

            BlockCurrentFrame();

            BindingsChanged?.Invoke();

            return true;
        }

        /// <summary>
        /// 保存済みのキー設定を削除する。
        ///
        /// 現在使用中のキー割り当てや、
        /// 同じファイル内の他データは変更しない。
        /// </summary>
        /// <returns>削除に成功した場合はtrue</returns>
        public bool DeleteSavedBindings()
        {
            if (saveProvider == null)
            {
                return false;
            }

            try
            {
                // ファイル全体ではなく対象キーのみ削除する。
                saveProvider.Delete(BindingSaveKey);
                saveProvider.Flush();

                return true;
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// 保存済みのキー設定が存在するか確認する。
        /// </summary>
        /// <returns>保存データが存在する場合はtrue</returns>
        public bool HasSavedBindings()
        {
            if (saveProvider == null)
            {
                return false;
            }

            try
            {
                return saveProvider.Exists(
                    BindingSaveKey);
            }
            catch (Exception exception)
            {
                Debug.LogWarning(
                    exception.Message,
                    this);

                return false;
            }
        }

        #endregion
    }
}
